import{_ as a,o as s,c as t,aa as n}from"./chunks/framework.vV0l90Ad.js";import"./chunks/theme.D160HLBh.js";const u=JSON.parse('{"title":"Node Development by Restart","description":"The namespace pattern makes class modules load coherently; an existing Node watcher can own code replacement without a second runtime for hot code swapping.","frontmatter":{"title":"Node Development by Restart","description":"The namespace pattern makes class modules load coherently; an existing Node watcher can own code replacement without a second runtime for hot code swapping.","search":false},"headers":[],"relativePath":"guide/node-class-hmr.md","filePath":"guide/node-class-hmr.md","lastUpdated":1786399507000}'),i={name:"guide/node-class-hmr.md"};function r(o,e,l,d,c,p){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="node-development-by-restart" tabindex="-1">Node Development by Restart <a class="header-anchor" href="#node-development-by-restart" aria-label="Permalink to &quot;Node Development by Restart&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Current exploration</p><p>This page defines the development boundary for the experimental Node namespace model. It is not an ivue package feature.</p></div><blockquote><p>A runtime should own only the problems the host runtime does not already solve.</p></blockquote><p>The Node namespace model solves authoring structure: circular dependencies resolve late, static methods are passable, inheritance remains native, and boot composition selects one class. A normal Node watcher already solves the remaining development event by restarting the process after an edit.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>edit</span></span>
<span class="line"><span>→ watcher stops the process</span></span>
<span class="line"><span>→ Node loads one fresh module graph</span></span>
<span class="line"><span>→ namespaces compose</span></span>
<span class="line"><span>→ routes retain methods from that generation</span></span>
<span class="line"><span>→ application runs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>The production and development application execute the same class paths. The watcher changes process lifetime, not class semantics.</p><h2 id="why-this-already-improves-class-reload" tabindex="-1">Why this already improves class reload <a class="header-anchor" href="#why-this-already-improves-class-reload" aria-label="Permalink to &quot;Why this already improves class reload&quot;">​</a></h2><p>Class-heavy module graphs often fail before an application can restart cleanly. An eager cross-module class read observes an uninitialized binding, or a static initializer performs work before its dependency exists.</p><p>The namespace grammar removes those eager value edges:</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E06C75;">static</span><span style="--shiki-light:#24292E;--shiki-dark:#E06C75;"> get</span><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;"> Users</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">() {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#C678DD;">  return</span><span style="--shiki-light:#24292E;--shiki-dark:#E5C07B;"> Users</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E06C75;">Class</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Imports may remain circular because dependency values are read only when behavior runs. A fresh Node process can therefore evaluate the graph in any module order permitted by the same late-read invariant.</p><p>Normal restart is not a fallback around broken class modules. The namespace shape makes normal restart dependable again.</p><h2 id="the-cost-of-keeping-the-process-alive" tabindex="-1">The cost of keeping the process alive <a class="header-anchor" href="#the-cost-of-keeping-the-process-alive" aria-label="Permalink to &quot;The cost of keeping the process alive&quot;">​</a></h2><p>Live class HMR inside Node requires much more than assigning a new constructor. A complete system must own:</p><ul><li>file watching and transitive module invalidation;</li><li>stable identities across re-evaluated module namespace objects;</li><li>transactional evaluation and rollback;</li><li>plugin recomposition against each new foundation;</li><li>callbacks already retained by routers, queues, and emitters;</li><li>active asynchronous frames from the previous generation;</li><li>explicit reconstruction and disposal of stateful instances;</li><li>static initialization, native private brands, and top-level side effects;</li><li>a cold-start verification path that catches hidden startup failures.</li></ul><p>That machinery becomes a second module runtime. It has its own correctness surface, tests, compatibility constraints, and maintenance cost. The namespace pattern makes such a runtime possible, but possibility does not make it part of the minimal backend contract.</p><h2 id="one-generation-is-the-coherence-boundary" tabindex="-1">One generation is the coherence boundary <a class="header-anchor" href="#one-generation-is-the-coherence-boundary" aria-label="Permalink to &quot;One generation is the coherence boundary&quot;">​</a></h2><p>A process restart keeps constructor wiring, static fields, closures, inheritance, private brands, retained callbacks, and process-owned resources within one evaluated generation. No old object receives behavior from a new declaration.</p><p>This is the same ownership principle used by ivue development: the framework or process owner reconstructs the owning boundary. The class transform does not implement a parallel replacement engine.</p><h2 id="resource-lifetime-remains-explicit" tabindex="-1">Resource lifetime remains explicit <a class="header-anchor" href="#resource-lifetime-remains-explicit" aria-label="Permalink to &quot;Resource lifetime remains explicit&quot;">​</a></h2><p>Restart discards in-memory resources. Development applications should make their important state reproducible through fixtures, external databases, seeded sessions, or explicit boot scripts.</p><p>Some systems have multi-minute warmup, irreplaceable in-memory investigations, or long-lived connections that make process preservation unusually valuable. Those systems may justify a managed module runner. That is a separate product with explicit resource, dispatch, and state-migration contracts. It is not a hidden obligation of every class module.</p><h2 id="the-reduction-boundary" tabindex="-1">The reduction boundary <a class="header-anchor" href="#the-reduction-boundary" aria-label="Permalink to &quot;The reduction boundary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Owner</th></tr></thead><tbody><tr><td>Circular-import safety</td><td>Namespace getters and late method bodies</td></tr><tr><td>Passable static callbacks</td><td><code>Static()</code> first-read binding</td></tr><tr><td>Inheritance and <code>super</code></td><td>Raw <code>$Class</code> declarations</td></tr><tr><td>Plugin selection</td><td>Boot-time kernel composition</td></tr><tr><td>Source-file watching</td><td>Existing Node development tool</td></tr><tr><td>Code replacement</td><td>Process restart</td></tr><tr><td>Durable state</td><td>External resource owner</td></tr><tr><td>Request-varying provider choice</td><td>Explicit context or scoped DI</td></tr></tbody></table><p>Removing live HMR preserves every selected capability. Adding it would expand scope without strengthening the namespace invariant.</p><h2 id="the-retained-possibility" tabindex="-1">The retained possibility <a class="header-anchor" href="#the-retained-possibility" aria-label="Permalink to &quot;The retained possibility&quot;">​</a></h2><p>The namespace&#39;s stable object and mutable <code>Class</code> slot remain useful seams for tests and boot-time plugins. They also provide the canonical identity a future live runtime would require. Nothing in the reduced design prevents a separate system from exploring that direction.</p><p>The default remains smaller:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>namespace + late getters + Static() + restart</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The <a href="/guide/namespace-pattern">Namespace Pattern</a> explains the cross-runtime invariant. <a href="/guide/static">Static() — Capability Classes</a> contains the working transform, tests, benchmarks, and exact scope.</p>`,30)])])}const b=a(i,[["render",r]]);export{u as __pageData,b as default};
